const setImportedPostDates = `-- name: SetImportedPostDates :exec
UPDATE posts
SET created_at = $1, changed_at = $2, first_published_at = $3
WHERE id = $4
`

type SetImportedPostDatesParams struct {
	CreatedAt        time.Time    `json:"created_at"`
	ChangedAt        time.Time    `json:"changed_at"`
	FirstPublishedAt sql.NullTime `json:"first_published_at"`
	ID               int64        `json:"id"`
}

// The export's dates, before the post is published: first_published_at can only be set
// while it is NULL (000061's trigger keeps the first value), so a published import keeps
// its original date for "close comments after N days" too.
func (q *Queries) SetImportedPostDates(ctx context.Context, arg SetImportedPostDatesParams) error {
	_, err := q.db.ExecContext(ctx, setImportedPostDates,
		arg.CreatedAt,
		arg.ChangedAt,
		arg.FirstPublishedAt,
		arg.ID,
	)
	return err
}
